int jump(const vector<int>& a) {
    int n = a.size(), jumps = 0, curEnd = 0, farthest = 0;
    for (int i = 0; i < n - 1; ++i) {
        farthest = max(farthest, i + a[i]);
        if (i == curEnd) {  // current range exhausted: must jump
            ++jumps;
            curEnd = farthest;
        }
    }
    return jumps;
}

