def partition_labels(s):
    last = {c: i for i, c in enumerate(s)}
    out, start, end = [], 0, 0
    for i, c in enumerate(s):
        end = max(end, last[c])
        if i == end:
            out.append(end - start + 1)
            start = i + 1
    return out

print(partition_labels("abacbdeffe"))

int leastInterval(const vector<char>& tasks, int n) {
    int cnt[26] = {0}, maxCount = 0, numMax = 0;
    for (char t : tasks) maxCount = max(maxCount, ++cnt[t - 'A']);
    for (int c : cnt) if (c == maxCount) ++numMax;
    return (maxCount - 1) * (n + 1) + numMax;
}
